const _TRI_PROBS_B64 = "";
const _TRI_DIVISOR = 16777215;

function getTrigramProb(cA, cB, cC) {
    // 二分查找
    let left = 0, right = _TRI_COUNT - 1;
    while (left <= right) {
        const mid = (left + right) >> 1;
        if (_TRI_A[mid] < cA) left = mid + 1;
        else if (_TRI_A[mid] > cA) right = mid - 1;
        else {
            if (_TRI_B[mid] < cB) left = mid + 1;
            else if (_TRI_B[mid] > cB) right = mid - 1;
            else {
                if (_TRI_C[mid] < cC) left = mid + 1;
                else if (_TRI_C[mid] > cC) right = mid - 1;
                else {
                    // 使用你现有的 base64To24bit 函数解码
                    const chunk = _TRI_PROBS_B64.substr(mid * 4, 4);
                    return base64To24bit(chunk) / _TRI_DIVISOR;
                }
            }
        }
    }
    return null;
}

function getModelScore(char, prevChar, prevPrevChar) {
    if (typeof compress !== 'function') return 0;
    const c2 = compress(prevChar);
    const c3 = compress(char);
    if (c2 === undefined || c3 === undefined) return 0;
    // 3‑gram
    if (prevPrevChar !== undefined) {
        const c1 = compress(prevPrevChar);
        if (c1 !== undefined) {
            const p3 = getTrigramProb(c1, c2, c3);
            if (p3 !== null) return p3;
        }
    }
    // bigram fallback
    const idx = c2 * _TOTAL_CODES + c3;
    const chunk = _PROBS_B64.substr(idx * 4, 4);
    const value24 = base64To24bit(chunk);
    return value24 / _PROBS_DIVISOR;
}
